fn shell_game(n: i32, x: i8) -> i8 {
    debug_assert!(n >= 1);
    debug_assert!((0..=2).contains(&x));

    // The transformation repeats every 6 moves (composition of swaps yields a 3-cycle).
    // So we only need n mod 6.
    let k = ((n % 6) + 6) % 6; // handle any unexpected negative n safely

    let mut pos = x;
    for i in 1..=k {
        if i % 2 == 1 {
            // odd: swap 0 <-> 1
            pos = match pos {
                0 => 1,
                1 => 0,
                _ => pos, // 2 stays
            };
        } else {
            // even: swap 1 <-> 2
            pos = match pos {
                1 => 2,
                2 => 1,
                _ => pos, // 0 stays
            };
        }
    }
    pos
}